-- Politicians
insert into public.politicians (slug, name, party, state, current_office, bio, career_history)
values ('ed-markey', 'Ed Markey', 'Democratic', 'MA', 'U.S. Senator', 'Ed Markey is a Democrat who has served as a U.S. Senator from Massachusetts since 2013, when he won a special election to fill the seat vacated by John Kerry. In 2026 he is seeking re-election against Republican John Deaton after defeating Rep. Seth Moulton in the Sept. 1 Democratic primary. He previously represented Massachusetts in the U.S. House from 1976 to 2013 and served in the Massachusetts House of Representatives from 1973 to 1976.', '[{"period":"1968-1973","role":"U.S. Army Reserve (Specialist 4)"},{"period":"1973-1976","role":"Member, Massachusetts House of Representatives"},{"period":"1976-2013","role":"U.S. Representative from Massachusetts (7th district; 5th district in 2013)"},{"period":"2007-2011","role":"Chair, House Select Committee on Energy Independence and Global Warming"},{"period":"2013-present","role":"U.S. Senator from Massachusetts"},{"period":"2025-present","role":"Ranking Member, Senate Small Business Committee"}]'::jsonb)
on conflict (slug) do update set
  name = excluded.name, party = excluded.party, state = excluded.state,
  current_office = excluded.current_office, bio = excluded.bio,
  career_history = excluded.career_history;
insert into public.politicians (slug, name, party, state, current_office, bio, career_history)
values ('john-deaton', 'John Deaton', 'Republican', 'MA', 'Republican nominee for U.S. Senate', 'John Deaton is an attorney and U.S. Marine Corps veteran who founded the Deaton Law Firm in East Providence, Rhode Island, in 2006, representing asbestos and mesothelioma plaintiffs, and who drew wide attention for representing XRP holders in the SEC''s case against Ripple Labs. He was the 2024 Republican nominee for U.S. Senate in Massachusetts, losing to Sen. Elizabeth Warren. In 2026 he ran unopposed in the Republican primary and is challenging Democratic Sen. Ed Markey in the Nov. 3 general election.', '[{"period":"1995-2002","role":"Judge advocate (prosecutor and defense attorney), U.S. Marine Corps"},{"period":"2002-2006","role":"Attorney, plaintiffs'' mesothelioma litigation firm"},{"period":"2006-present","role":"Founder, Deaton Law Firm (East Providence, R.I.)"},{"period":"2024","role":"Republican nominee for U.S. Senate in Massachusetts"},{"period":"2026-present","role":"Republican nominee for U.S. Senate in Massachusetts"}]'::jsonb)
on conflict (slug) do update set
  name = excluded.name, party = excluded.party, state = excluded.state,
  current_office = excluded.current_office, bio = excluded.bio,
  career_history = excluded.career_history;
insert into public.politicians (slug, name, party, state, current_office, bio, career_history)
values ('maura-healey', 'Maura Healey', 'Democratic', 'MA', 'Governor of Massachusetts', 'Maura Healey has served as the 73rd governor of Massachusetts since January 2023 and is seeking a second term in the November 3, 2026 general election against Republican Mike Minogue, after winning the Democratic nomination unopposed on September 1, 2026. She previously served as Massachusetts Attorney General from 2015 to 2023. Before that, she led the Civil Rights Division and later two bureaus in the Attorney General''s Office.', '[{"period":"1992-1994","role":"Professional basketball player, UBBC Wüstenrot Salzburg (Austria)"},{"period":"2007-2012","role":"Chief, Civil Rights Division, Massachusetts Attorney General''s Office"},{"period":"2012-2013","role":"Chief, Public Protection and Advocacy Bureau, then Chief, Business and Labor Bureau, Massachusetts Attorney General''s Office"},{"period":"2015-2023","role":"Attorney General of Massachusetts"},{"period":"2023-present","role":"Governor of Massachusetts"}]'::jsonb)
on conflict (slug) do update set
  name = excluded.name, party = excluded.party, state = excluded.state,
  current_office = excluded.current_office, bio = excluded.bio,
  career_history = excluded.career_history;
insert into public.politicians (slug, name, party, state, current_office, bio, career_history)
values ('mike-minogue', 'Mike Minogue', 'Republican', 'MA', 'Republican nominee for Governor', 'Mike Minogue is a businessman and U.S. Army veteran who served in Operation Desert Storm and later led the Danvers-based medical device company Abiomed as president and CEO from 2004 until its acquisition by Johnson & Johnson in 2022. A first-time candidate, he entered the 2026 race for governor in October 2025 and won the Republican nomination over Brian Shortsleeve in the September 2026 primary. He is challenging incumbent Democratic Gov. Maura Healey in the Nov. 3, 2026 general election.', '[{"period":"1989-1993","role":"U.S. Army infantry officer; served in Operation Desert Storm"},{"period":"1990s-2004","role":"Management positions at GE Medical Systems"},{"period":"2004-2022","role":"President and CEO of Abiomed (chairman of the board from 2005)"},{"period":"2025-present","role":"Candidate for Governor of Massachusetts (Republican nominee since September 2026)"}]'::jsonb)
on conflict (slug) do update set
  name = excluded.name, party = excluded.party, state = excluded.state,
  current_office = excluded.current_office, bio = excluded.bio,
  career_history = excluded.career_history;

