insert into public.politician_news_summaries (politician_id, summary, citations, article_count, model, generated_at)
select p.id, 'Gov. Maura Healey and Republican challenger Mike Minogue held their second and final debate on Oct. 15, where Healey again linked Minogue to President Donald Trump and cited her record on tax relief, housing, health care costs and education [2]. Minogue questioned her oversight of state government, pointing to former Healey aide LaMar Cook, who was arrested Oct. 14 on federal SNAP and wire fraud charges after being fired in 2025 over state drug and gun charges [1][2]. Healey said Cook was fired immediately after his first arrest and said she was glad federal prosecutors had acted, while Minogue called the case a failure at every level [1][2]. The candidates also split on State Police misconduct, abortion access, immigration enforcement and energy, with Healey backing an all-of-the-above energy approach and Minogue calling for more natural gas pipeline capacity [2].

After Minogue''s running mate, Shawn Oliver, suspended his lieutenant governor campaign following a drunken-driving arrest, Healey said on Oct. 19 that the Minogue campaign was in chaos and that she would stay focused on costs, housing and energy bills [4]. Minogue responded that Healey holds no one accountable, citing her debate remark that sometimes things happen [4]. In an NBC Boston interview, Healey said she agrees with Minogue that the Legislature should comply with the voter-approved audit and that she has pressed legislative leaders to do so [8].

The House left Healey''s proposed two-month suspension of the 24-cent gas tax out of a roughly $2.4 billion spending bill, with House leaders arguing it would limit infrastructure funding without ensuring savings reach drivers [6]. A Healey spokesperson said she would keep pushing for the estimated $120 million in relief, while Minogue, who proposed his own suspension first, called her plan a political stunt [6]. Boston.com noted that Healey opposed a gas tax suspension in 2022 and now says the war with Iran makes one necessary [6]. Healey told NBC Boston she would keep pushing for the pause as long as the war continues and prices stay high [8].

A UMass Amherst/WCVB poll conducted Oct. 5-12 found Healey leading Minogue 57% to 32%, and the poll''s director said her effort to tie Minogue to Trump appeared to be working [3]. A Suffolk University/Boston Globe poll taken Oct. 14-17 showed Healey ahead by more than 58% to 36%, even as more than 42% of respondents said the state had gotten worse over the past four years [5]. The Boston Globe editorial board endorsed Healey for reelection, crediting her response to federal cuts and her housing plan while calling her campaign uninspiring and urging more focus on the state''s economy [7].', '[{"n":1,"title":"Lamar Cook, former Maura Healey staffer facing gun and drug charges, now accused of SNAP fraud","url":"https://www.cbsnews.com/boston/news/lamar-cook-maura-healey-snap-fraud-arrest/","source":"CBS News Boston","published_at":"2026-10-14"},{"n":2,"title":"Healey and Minogue made their final pitches to voters in a tense debate. Here are 4 takeaways.","url":"https://www.boston.com/news/politics/2026/10/16/healey-and-minogue-made-their-final-pitches-to-voters-in-a-tense-debate-here-are-4-takeaways/","source":"Boston.com","published_at":"2026-10-16"},{"n":3,"title":"Trump''s shadow affects Minogue negatively in Mass. governor''s race, UMass Amherst/WCVB poll finds","url":"https://www.wcvb.com/article/umass-poll-healey-minogue-trump-markey-deaton-election-2026/74167943","source":"WCVB","published_at":"2026-10-19"},{"n":4,"title":"Healey claims Minogue campaign ''chaos'' following Oliver arrest","url":"https://www.berkshireeagle.com/localnews/healey-claims-minogue-campaign-chaos-following-oliver-arrest/5040077","source":"The Berkshire Eagle (State House News Service)","published_at":"2026-10-20"},{"n":5,"title":"Nearly half of voters in pre-election poll say Mass. has gotten worse over 4 years","url":"https://www.wgbh.org/news/politics/2026-10-20/nearly-half-of-voters-in-pre-election-poll-say-mass-has-gotten-worse-over-4-years","source":"GBH News","published_at":"2026-10-20"},{"n":6,"title":"Legislature erases Healey’s gas tax holiday proposal","url":"https://www.boston.com/news/politics/2026/10/21/legislature-erases-healeys-gas-tax-holiday-proposal/","source":"Boston.com","published_at":"2026-10-21"},{"n":7,"title":"Globe endorses Governor Maura Healey for reelection","url":"https://www.bostonglobe.com/2026/10/22/opinion/healey-governor-endorsements/","source":"The Boston Globe (Editorial)","published_at":"2026-10-22"},{"n":8,"title":"Healey makes pitch in interview: ‘It''s never mattered more who your governor is''","url":"https://www.nbcboston.com/news/politics/healey-makes-pitch-in-interview-its-never-mattered-more-who-your-governor-is/4036583/?partner=amazon-ai","source":"NBC Boston","published_at":"2026-10-23"}]'::jsonb, 8, 'Kiro sub-agent research (news from Oct 10-24, 2026)', now()
from public.politicians p where p.slug = 'maura-healey'
