insert into public.politician_news_summaries (politician_id, summary, citations, article_count, model, generated_at)
select p.id, 'Minogue and Gov. Maura Healey met Oct. 15 for their second and final debate, clashing over the cost of living, energy, housing, immigration and government accountability [1][2]. Minogue called for cutting the gas tax and utility fees, blamed Healey for blocking natural gas pipelines as attorney general, and pressed her over a fired aide facing drug and fraud charges [2][3]. PolitiFact found his pipeline and electricity-cost claims accurate but said his attacks over the aide and his use of a Healey quote needed context [3]. On abortion, Minogue said he would follow the law regardless of his personal beliefs, while Healey said he does not trust women, a charge he called a cheap shot [1].

On Oct. 18, running mate Shawn Oliver suspended his lieutenant governor campaign after an OUI arrest following a crash in New Bedford, after Minogue publicly urged him to step aside and said he would seek Oliver''s resignation if both won [4]. Oliver''s name remains on the ballot, and Republicans quoted by the Globe were split between calling the episode an unforced error and predicting little effect on the governor''s race [4]. Minogue later said Oliver would not serve as his lieutenant governor and urged voters not to cross Oliver''s name off their ballots, warning it could invalidate their vote [7][8].

A UMass Amherst/WCVB poll taken Oct. 5-12 showed Healey leading Minogue 57% to 32%, and a Suffolk University/Boston Globe poll released Oct. 20 put her lead at 23 points, with 21% of likely voters saying they had not heard of him [5][8]. After casting his early ballot in Hamilton on Oct. 22, Minogue dismissed the public polls and cited internal campaign polling he said showed a single-digit race, which his campaign did not immediately provide [8]. He spent a record $6.1 million in September, and Healey''s campaign criticized his donations to a committee that backed President Trump [8]. A pro-Minogue super PAC also began targeting independent candidate Andrea James with ads and mailers; its chairman called it a matter of principle, while one political scientist said it appeared aimed at drawing votes away from Healey [6].

In a live Boston 25 News interview, Minogue called for eliminating the state''s 24-cent gas tax, said he would never raise taxes, and pledged to forgo a governor''s salary and have an outside firm audit every state agency [7]. He listed disagreements with Trump on tariffs, rhetoric, the trade dispute with Canada and NIH cuts, and said immigration enforcement should be coordinated with local officials and prioritize violent criminals and drug dealers [2][7].', '[{"n":1,"title":"Healey and Minogue meet in unbridled final debate before election","url":"https://www.wbur.org/news/2026/10/15/healey-and-minogue-meet-in-unbridled-final-debate-before-election","source":"WBUR","published_at":"2026-10-15"},{"n":2,"title":"Healey, Minogue clash over costs, housing and energy in final Massachusetts gubernatorial debate","url":"https://www.wcvb.com/article/healey-minogue-final-debate-oct-15-2026-live-udpates-stream/74133861","source":"WCVB","published_at":"2026-10-15"},{"n":3,"title":"Fact-checking Healey, Minogue in final MA governor debate","url":"https://politifact.com/article/2026/oct/15/massachusetts-governor-debate-healey-minogue/","source":"PolitiFact","published_at":"2026-10-15"},{"n":4,"title":"Shawn Oliver suspends lieutenant governor campaign after OUI charge","url":"https://www.bostonglobe.com/2026/10/18/metro/oliver-oui-lieutenant-governor-nominee/","source":"The Boston Globe","published_at":"2026-10-18"},{"n":5,"title":"A new poll takes the temperature on the Mass. governor''s race — and all 9 ballot questions","url":"https://www.wbur.org/news/2026/10/19/massachusetts-governors-race-ballot-question-poll","source":"WBUR","published_at":"2026-10-19"},{"n":6,"title":"Why is a pro-Mike Minogue super PAC targeting Mass. governor candidate Andrea James?","url":"https://www.wgbh.org/news/politics/2026-10-21/why-is-a-pro-mike-minogue-super-pac-targeting-mass-governor-candidate-andrea-james","source":"GBH News","published_at":"2026-10-21"},{"n":7,"title":"What would Mike Minogue change as Mass. governor? GOP candidate makes his case in 1-on-1 interview","url":"https://www.boston25news.com/news/local/what-would-mike-minogue-change-mass-governor-gop-candidate-makes-his-case-1-on-1-interview/JDX7WAHHWREBTAZZA3CHWI5HYY/","source":"Boston 25 News","published_at":"2026-10-22"},{"n":8,"title":"After a week of setbacks, GOP''s Minogue goes on the offensive","url":"https://www.bostonglobe.com/2026/10/22/metro/minogue-votes-governors-race-polling-healey/","source":"The Boston Globe","published_at":"2026-10-22"}]'::jsonb, 8, 'Kiro sub-agent research (news from Oct 10-24, 2026)', now()
